use crate::{model::RelayEvent, providers::SourceAdapter};
use anyhow::{Result, anyhow, ensure};
use axum::http::HeaderMap;
use hmac::{Hmac, Mac};
use serde_json::{Value, json};
use sha2::Sha256;
use std::sync::LazyLock;

// Generated by scripts/github_catalog.py from GitHub's webhook OpenAPI description.
static DEFINITIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!("github_events.json")).expect("GitHub event definitions")
});

pub struct GitHub;
impl SourceAdapter for GitHub {
    fn descriptor(&self) -> Value {
        let names: serde_json::Map<String, Value> = DEFINITIONS
            .as_object()
            .unwrap()
            .iter()
            .map(|(kind, definition)| (kind.clone(), definition["name"].clone()))
            .collect();
        json!({"id":"github","name":"GitHub","category":"代码托管",
          "fields":[{"key":"key_id","label":"Webhook Secret","required":true,"type":"secret","role":"verification"}],
          "defaults":{"key_id":""},
          "event_types":names,
          "sample":DEFINITIONS["ping"]["sample"],
          "event_definitions":*DEFINITIONS
        })
    }
    fn signature_header(&self) -> &'static str {
        "x-hub-signature-256"
    }
    fn verify(&self, raw: &[u8], signature: &str, secret: &str) -> Result<()> {
        let digest = hex::decode(
            signature
                .strip_prefix("sha256=")
                .ok_or_else(|| anyhow!("invalid signature"))?,
        )?;
        let mut mac = Hmac::<Sha256>::new_from_slice(secret.as_bytes())?;
        mac.update(raw);
        mac.verify_slice(&digest)
            .map_err(|_| anyhow!("invalid signature"))
    }
    fn normalize(&self, headers: &HeaderMap, raw: &[u8], source_name: &str) -> Result<RelayEvent> {
        let header = |name: &str, max: usize| {
            headers
                .get(name)
                .and_then(|v| v.to_str().ok())
                .filter(|s| !s.is_empty() && s.len() <= max)
                .ok_or_else(|| anyhow!("{name} is required"))
        };
        let event = header("x-github-event", 64)?;
        let id = header("x-github-delivery", 256)?.to_owned();
        let raw: Value = serde_json::from_slice(raw)?;
        ensure!(raw.is_object(), "payload must be an object");
        // Events are keyed by event.action, except those catalogued without one
        // because their action is free-form (repository_dispatch).
        let event_type = match raw["action"].as_str() {
            Some(action) if DEFINITIONS.get(event).is_none() => format!("{event}.{action}"),
            _ => event.to_owned(),
        };
        ensure!(event_type.len() <= 128, "event type exceeds limit");
        let scope = raw
            .pointer("/repository/full_name")
            .or(raw.pointer("/organization/login"))
            .and_then(Value::as_str)
            .unwrap_or("GitHub");
        let name = DEFINITIONS[&event_type]["name"]
            .as_str()
            .unwrap_or(&event_type);
        Ok(RelayEvent {
            id,
            summary: format!("{scope} · {name}"),
            event_type,
            source_name: source_name.into(),
            raw,
        })
    }
}
